using System.Windows;using OdinVault.Manager.Wpf.ViewModels;namespace OdinVault.Manager.Wpf.Views;public partial class StorageView:System.Windows.Controls.UserControl{public StorageView(){InitializeComponent();}void Replica_Click(object s,RoutedEventArgs e){if(DataContext is StorageViewModel vm){var w=new ReplicaWindow{Owner=Window.GetWindow(this),DataContext=new ReplicaViewModel(vm.Client)};w.ShowDialog();_ = vm.LoadAsync();}}async void Edit_Click(object s,RoutedEventArgs e){if(DataContext is not StorageViewModel vm||vm.Selected is null){System.Windows.MessageBox.Show("ابتدا یک مقصد ذخیره‌سازی را انتخاب کنید.","OdinVault");return;}var dialog=new StorageTargetEditWindow(vm.Selected){Owner=Window.GetWindow(this)};if(dialog.ShowDialog()!=true)return;try{await vm.Client.UpdateStorageAsync(vm.Selected.Id,dialog.Request);await vm.LoadAsync();System.Windows.MessageBox.Show("تغییرات مقصد ذخیره شد.","OdinVault");}catch(Exception ex){System.Windows.MessageBox.Show(ex.Message,"OdinVault");}}}